code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    # repeated bands define palette, reverse the order after the leading band
    seq=[]
    for row in grid:
        c=row[0]
        if c and c not in seq: seq.append(c)
    if len(seq)>1: seq=[seq[0]]+list(reversed(seq[1:]))
    return [[seq[r%len(seq)]]*w for r in range(h)]
'''; open(p,'w').write(code); exec(code); print(transform([[5]*9,[0]*9,[2]*9,[1]*9,[9]*9,[9]*9,[9]*9,[0]*9,[9]*9]))
